#!/usr/bin/env python3
"""Restore exact CC0 sand derivative offline. Provenance: DUNES-GROUND-VALIDATION.md."""
from pathlib import Path
import base64, hashlib
DATA = ''
raw=base64.b64decode(DATA)
assert hashlib.sha256(raw).hexdigest()=="2188be2317809a95a14f53b64814042c8e0d5907e65cbf8da2b1092222ecd5a2"
p=Path(__file__).parent/'assets/textures/dunes_ripple_sand.jpg'
p.parent.mkdir(parents=True,exist_ok=True)
p.write_bytes(raw)
# Stable non-VRAM lossy import and mipmaps for browser-first use.
Path(str(p)+'.import').write_text('[remap]\n\nimporter="texture"\ntype="CompressedTexture2D"\nuid="uid://c35eftea1xtb8"\npath="res://.godot/imported/dunes_ripple_sand.jpg-b27f4295c5d30539068f9e3b340205fe.ctex"\nmetadata={\n"vram_texture": false\n}\n\n[deps]\n\nsource_file="res://assets/textures/dunes_ripple_sand.jpg"\ndest_files=["res://.godot/imported/dunes_ripple_sand.jpg-b27f4295c5d30539068f9e3b340205fe.ctex"]\n\n[params]\n\ncompress/mode=1\ncompress/high_quality=false\ncompress/lossy_quality=0.7\ncompress/uastc_level=0\ncompress/rdo_quality_loss=0.0\ncompress/hdr_compression=1\ncompress/normal_map=0\ncompress/channel_pack=0\nmipmaps/generate=true\nmipmaps/limit=-1\nroughness/mode=0\nroughness/src_normal=""\nprocess/channel_remap/red=0\nprocess/channel_remap/green=1\nprocess/channel_remap/blue=2\nprocess/channel_remap/alpha=3\nprocess/fix_alpha_border=true\nprocess/premult_alpha=false\nprocess/normal_map_invert_y=false\nprocess/hdr_as_srgb=false\nprocess/hdr_clamp_exposure=false\nprocess/size_limit=0\ndetect_3d/compress_to=1\n')
print(p, len(raw))
